<script setup lang="ts">
import { computed } from 'vue'
import type { BaselineDate } from '@/dashboard/composables/useEventStatus'

const props = defineProps<{
  text: string
  /** Same milestone's date in each project baseline, latest first */
  baselines?: BaselineDate[]
}>()

const lines = computed(() => (props.text ? props.text.split('\n') : []))
</script>

<template>
  <div>
    <div
      v-for="(line, index) in lines"
      :key="index"
      :class="index === 0 ? 'primary-line' : 'note-line'"
    >
      {{ line }}
    </div>
    <div
      v-for="baseline in baselines ?? []"
      :key="baseline.label + baseline.title"
      class="baseline-line"
      :title="`${baseline.title}: ${baseline.date}`"
    >
      <span class="baseline-label">{{ baseline.label }}:</span> {{ baseline.date }}
    </div>
  </div>
</template>

